  async function research(kind,answer="",questionIndex=0,taskId=null,sourceStepId=null,question="",extras={}){
    if(career.busy)return;if(["role","map"].includes(kind)&&storyDraft().proof){notify("先保存或取消正在编辑的证据对照，再重新分析岗位。");return;}captureDrafts();
    if(kind==="interview"){const [focus,id]=(storyDraft().interview_focus||"").split(":");extras={...extras,...(focus==="story"?{story_id:id}:focus==="task"?{task_id:id}:{})};}
    career.busy=true;renderDetail();
    const id=career.id;
    try{
      const step=await api("career/"+id+"/prepare",{method:"POST",body:JSON.stringify({kind,answer,question_index:questionIndex,task_id:taskId,source_step_id:sourceStepId,question,section:career.tab,offline:Boolean(career.offline),allow_public:Boolean(storyDraft().allow_public)&&!career.offline&&!demoMode,...extras})});
      if(["interview","teachback","followup"].includes(kind)){const draft=career.drafts.get(id)||{};draft.next_source_step_id=step.step_id;draft.question_index="0";career.drafts.set(id,draft);}
      await api("projects/"+id+"/run",{method:"POST",body:JSON.stringify({step_id:step.step_id})});
      await openCareer(id);
      const section=career.data?.results.find(row=>row.step_id===step.step_id)?.section;
      if(kind==="ask"&&career.id===id&&section&&section!==career.tab){captureDrafts();career.tab=section;history.replaceState(null,"","#career/"+id+"/tab/"+section);renderDetail();}
    }catch(error){notify(error.message,true);}
    finally{career.busy=false;if(career.id===id)renderDetail();}
  }

